{
  "background_need": "Kuvitteellisen Saarikylän aikuisilla on vähän saavutettavia kulttuuriharrastuksia. Vapaaehtoiset ehdottavat kuuden kuukauden taidetyöpajoja, mutta osallistumisen esteitä ei ole kartoitettu.",
  "objectives": [
    {
      "id": "O1",
      "description": "Osallistujat kokevat osallistumisen mahdolliseksi ja löytävät itselleen sopivan kulttuuritoiminnan."
    },
    {
      "id": "O2",
      "description": "Lähtötilanteen esteiden tunnistaminen ja toimintamallin testaaminen."
    }
  ],
  "target_groups": [
    "Kuvitteelliset kulttuuritoiminnasta kiinnostuneet aikuiset"
  ],
  "preliminary_activities": [
    {
      "id": "A1",
      "description": "Osallistumisen esteiden kartoituskysely (esim. aikarajojen, taloudellisten tai sosiaalisten barjierien tunnistaminen).",
      "objective_ids": ["O2"]
    },
    {
      "id": "A2",
      "description": "Pieniä taidetyöpajoja (esim. 4 viikkoa) toteuttaminen kokeilumallina.",
      "objective_ids": ["O1", "O2"]
    }
  ],
  "expected_results": [
    {
      "id": "R1",
      "description": "Osallistujien osallistumisesta saatu palautteet (kyselytiedot).",
      "activity_ids": ["A1"]
    },
    {
      "id": "R2",
      "description": "Toteutettujen työpajojen määrä ja osallistujamäärä.",
      "activity_ids": ["A2"]
    },
    {
      "id": "R3",
      "description": "Osallistujien kertomukset kulttuuritoiminnan merkityksestä (haastattelut).",
      "activity_ids": ["A1", "A2"]
    }
  ],
  "proposed_indicators": [
    {
      "id": "I1",
      "description": "Osallistujien kertomus osallistumisen mahdollisuudesta (1-5 asteikko).",
      "result_ids": ["R3"],
      "measurement_method": "Kyselytiedustelu ennen ja jälkeen työpajat, 5-vaiheinen skalaari (1=mahdoton, 5=helppo). Lasketaan keskiarvo osallistujien välillä. Mittausajankohta: Työpajan päätyttyä."
    },
    {
      "id": "I2",
      "description": "Osallistujamäärä (yksilöt).",
      "result_ids": ["R2"],
      "measurement_method": "Kysymyksen vastauksien laskeminen. Mittausajankohta: Työpajan päätyttyä."
    },
    {
      "id": "I3",
      "description": "Osallistujien kertomus kulttuuritoiminnan merkityksestä (positiivinen vastausprosentti).",
      "result_ids": ["R3"],
      "measurement_method": "Kysymyksen vastauksien laskeminen. Mittausajankohta: Työpajan päätyttyä."
    }
  ],
  "assumptions": [
    "Osallistujat ovat valmiita osallistumaan taidetyöpajoihin ilman ennakko-erityisosaamista.",
    "Kuvitteellinen Saarikylän Taidekerho pystyy tarjoamaan tilaa ja materiaaleja työpajojen ajaksi.",
    "Osallistujilla on mahdollisuus osallistua työpajoihin (esim. työaikarajat, matkustusmahdollisuudet)."
  ],
  "open_questions": [
    "Mitkä ovat kuvitteellisen Saarikylän aikuisille tärkeitä esteitä kulttuuritoiminnan osallistumiselle?",
    "Miten työpajojen pituus ja taiteen laatu vaikuttavat osallistujien motivaatioon?",
    "Onko kuvitteellisella Taidekerholla resurssi toteuttaa kuuden kuukauden mittainen toiminta?"
  ]
}
